import { generateId } from '../ids.js';
import { type BimState, type Dimension, type ElementId } from '../types.js';

/**
 * Génère automatiquement les chaînes de cotation 2D pour un étage complet :
 * 1. Chaîne intérieure : trumeaux et baies (portes et fenêtres) avec déport extérieur à 650 mm.
 * 2. Chaîne extérieure : longueur globale hors-tout avec déport extérieur à 1 150 mm.
 *
 * Toutes les cotes produites sont associatives à leur mur hôte et portent le drapeau autoGenerated: true.
 */
export function computeAutoDimensionsForLevel(
  state: BimState,
  levelId: ElementId,
): Dimension[] {
  const result: Dimension[] = [];
  const levelWalls = Object.values(state.walls).filter((w) => w.levelId === levelId);
  if (levelWalls.length === 0) return result;

  // 1. Calcul du centre de la boîte englobante de l'étage
  let minX = Infinity;
  let maxX = -Infinity;
  let minY = Infinity;
  let maxY = -Infinity;
  for (const w of levelWalls) {
    minX = Math.min(minX, w.start.x, w.end.x);
    maxX = Math.max(maxX, w.start.x, w.end.x);
    minY = Math.min(minY, w.start.y, w.end.y);
    maxY = Math.max(maxY, w.start.y, w.end.y);
  }
  const cx = (minX + maxX) / 2;
  const cy = (minY + maxY) / 2;

  // Test d'intersection de segments pour le lancer de rayon extérieur
  function segIntersect(
    p1: { x: number; y: number },
    p2: { x: number; y: number },
    p3: { x: number; y: number },
    p4: { x: number; y: number },
  ): boolean {
    const d = (p2.x - p1.x) * (p4.y - p3.y) - (p2.y - p1.y) * (p4.x - p3.x);
    if (Math.abs(d) < 1e-6) return false;
    const t = ((p3.x - p1.x) * (p4.y - p3.y) - (p3.y - p1.y) * (p4.x - p3.x)) / d;
    const u = ((p3.x - p1.x) * (p2.y - p1.y) - (p3.y - p1.y) * (p2.x - p1.x)) / d;
    return t > 0.001 && t < 0.999 && u > 0.001 && u < 0.999;
  }

  // 2. Détection des murs de façade extérieurs
  for (const wall of levelWalls) {
    const dx = wall.end.x - wall.start.x;
    const dy = wall.end.y - wall.start.y;
    const wallLen = Math.hypot(dx, dy);
    if (wallLen < 100) continue;

    const ux = dx / wallLen;
    const uy = dy / wallLen;
    const nx = -uy;
    const ny = ux;

    const mx = (wall.start.x + wall.end.x) / 2;
    const my = (wall.start.y + wall.end.y) / 2;

    // Détermination de la normale extérieure (s'éloignant du centre)
    const dot = (mx - cx) * nx + (my - cy) * ny;
    const sign = dot >= 0 ? 1 : -1;
    const outNx = sign * nx;
    const outNy = sign * ny;

    // Rayon sortant de 20 mm à 100 000 mm
    const rStart = { x: mx + outNx * 20, y: my + outNy * 20 };
    const rEnd = { x: mx + outNx * 100000, y: my + outNy * 100000 };

    let hitsOther = false;
    for (const other of levelWalls) {
      if (other.id === wall.id) continue;
      if (segIntersect(rStart, rEnd, other.start, other.end)) {
        hitsOther = true;
        break;
      }
    }

    if (hitsOther) continue;

    // 3. Collecte des baies (portes et fenêtres) sur ce mur
    interface OpeningSpan {
      readonly start: number;
      readonly end: number;
    }
    const spans: OpeningSpan[] = [];

    // Portes
    if (state.doors) {
      for (const door of Object.values(state.doors)) {
        if (door.hostWallId === wall.id) {
          const dt = state.doorTypes?.[door.doorTypeId];
          const w = dt?.width ?? 900;
          spans.push({
            start: Math.max(0, Math.min(wallLen, door.offsetAlong)),
            end: Math.max(0, Math.min(wallLen, door.offsetAlong + w)),
          });
        }
      }
    }

    // Fenêtres
    if (state.windows) {
      for (const win of Object.values(state.windows)) {
        if (win.hostWallId === wall.id) {
          const wt = state.windowTypes?.[win.windowTypeId];
          const w = wt?.width ?? 1200;
          spans.push({
            start: Math.max(0, Math.min(wallLen, win.offsetAlong)),
            end: Math.max(0, Math.min(wallLen, win.offsetAlong + w)),
          });
        }
      }
    }

    spans.sort((a, b) => a.start - b.start);

    // Déports étagés vers l'extérieur :
    // 1. Chaîne intérieure trumeaux & baies : déport 650 mm
    // 2. Chaîne extérieure hors-tout : déport 1 150 mm
    const innerOffset = sign * 650;
    const outerOffset = sign * 1150;

    // A. Chaîne intérieure : Trumeaux et Baies
    if (spans.length > 0) {
      let curOffset = 0;
      for (const op of spans) {
        if (op.start > curOffset + 10) {
          const trumeauLen = Math.round(op.start - curOffset);
          result.push({
            id: generateId(),
            category: 'dimension',
            levelId,
            type: 'aligned',
            references: [wall.id],
            span: { startOffset: curOffset, endOffset: op.start },
            offset: innerOffset,
            value: trumeauLen,
            autoGenerated: true,
          });
        }

        const baieLen = Math.round(op.end - op.start);
        if (baieLen > 10) {
          result.push({
            id: generateId(),
            category: 'dimension',
            levelId,
            type: 'aligned',
            references: [wall.id],
            span: { startOffset: op.start, endOffset: op.end },
            offset: innerOffset,
            value: baieLen,
            autoGenerated: true,
          });
        }

        curOffset = op.end;
      }

      if (wallLen > curOffset + 10) {
        const lastTrumeauLen = Math.round(wallLen - curOffset);
        result.push({
          id: generateId(),
          category: 'dimension',
          levelId,
          type: 'aligned',
          references: [wall.id],
          span: { startOffset: curOffset, endOffset: wallLen },
          offset: innerOffset,
          value: lastTrumeauLen,
          autoGenerated: true,
        });
      }
    }

    // B. Chaîne extérieure : Cote globale hors-tout
    result.push({
      id: generateId(),
      category: 'dimension',
      levelId,
      type: 'aligned',
      references: [wall.id],
      offset: outerOffset,
      value: Math.round(wallLen),
      autoGenerated: true,
    });
  }

  return result;
}
